function sumOfPower(nums) {
  const MOD = 1000000007n;
  nums.sort((a, b) => a - b);
  let total = 0n;
  let minSum = 0n;

  for (const num of nums) {
    const value = BigInt(num);
    const maxSquared = value * value % MOD;
    total = (total + maxSquared * (minSum + value)) % MOD;
    minSum = (minSum * 2n + value) % MOD;
  }
  return Number(total);
}

