function sumOfPower(nums) {
  // Enumerate every non-empty subset by bitmask and add max^2 * min directly.
  const n = nums.length;
  let total = 0n;
  for (let mask = 1; mask < (1 << n); mask++) {
    let high = -Infinity;
    let low = Infinity;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        high = Math.max(high, nums[i]);
        low = Math.min(low, nums[i]);
      }
    }
    total += BigInt(high) * BigInt(high) * BigInt(low);
  }
  return Number(total % 1000000007n);
}

