function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const mode = Math.floor(rand() * 4);
    if (mode === 0) return [Array.from({ length: n }, () => pick(1, 4))];
    if (mode === 1) return [Array.from({ length: n }, () => pick(999999990, 1000000000))];
    if (mode === 2) {
      const same = pick(1, 1000000000);
      return [Array.from({ length: n }, () => same)];
    }
    return [Array.from({ length: n }, () => pick(1, 1000))];
  }
  const n = pick(1500, 2000);
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [Array.from({ length: n }, () => pick(1, 5))];
  if (mode === 1) return [Array.from({ length: n }, () => pick(900000000, 1000000000))];
  return [Array.from({ length: n }, () => pick(1, 1000000000))];
}
